--[=[
    @class IHost
]=]

--[=[
	@prop Services IServiceProvider
	@within IHost
	@readonly
	服务提供者
]=]
export type IHost = {
    Services: IServiceProvider,

    --- 启动主机
    Start: (self: IHost) -> (),

    --- 停止主机
    End: (self: IHost) -> (),

    --- 销毁主机
    Dispose: (self: IHost) -> ()
}

return {}
